'use strict'

// Reproduces the pre-fix behaviour: a single large write on an HTTP/2 stream
// that gets cancelled leaves the session unusable.
const http2 = require('node:http2')

const CHUNK = Number(process.env.CHUNK) || 0 // 0 = single write (pre-fix)
const big = Buffer.alloc(32 * 1024 * 1024, 'a')

const server = http2.createServer((req, res) => {
  if (req.url === '/small') {
    res.writeHead(200, { 'content-type': 'application/json' })
    res.write('{"hello":"world"}')
    res.end()
    return
  }
  res.writeHead(200, { 'content-type': 'application/octet-stream', 'content-length': '' + big.length })
  if (CHUNK === 0) {
    res.write(big)
    res.end()
    return
  }
  let offset = 0
  function write () {
    while (offset < big.length) {
      if (res.writableEnded || (res.stream && res.stream.destroyed)) return
      const end = offset + CHUNK
      const backpressure = res.write(big.subarray(offset, end)) === false
      offset = end
      if (backpressure && offset < big.length) {
        res.once('drain', write)
        return
      }
    }
    res.end()
  }
  write()
})

server.listen(0, async () => {
  const session = http2.connect(`http://localhost:${server.address().port}`)
  await new Promise(resolve => {
    const s = session.request({ ':path': '/big' })
    s.on('error', () => {})
    s.on('response', () => s.close(http2.constants.NGHTTP2_CANCEL))
    s.on('close', resolve)
    s.end()
  })

  const result = await Promise.race([
    new Promise((resolve, reject) => {
      const s = session.request({ ':path': '/small' })
      let data = ''
      s.setEncoding('utf8')
      s.on('data', c => { data += c })
      s.on('end', () => resolve(data))
      s.on('error', reject)
      s.end()
    }).catch(err => 'ERROR: ' + err.code),
    new Promise(resolve => setTimeout(() => resolve('TIMEOUT (session poisoned)'), 5000))
  ])

  console.log(`CHUNK=${CHUNK} ->`, result)
  session.destroy()
  server.close()
  process.exit(0)
})

