const decorators = require('./decorate')

const toString = Object.prototype.toString

// HTTP/2 queues a whole `write()` inside the session before it is framed.
// When the client cancels the stream while such a write is still pending,
// the session is left with the unsent data and every following request on
// it stalls. Writing large payloads in smaller pieces keeps the amount of
// queued data bounded, so the session survives the cancellation.
const HTTP2_MAX_CHUNK_SIZE = Infinity // TEMPORARY: verify the test reproduces the bug

function Reply (res, request, log) {
  this.raw = res
  this[kReplySerializer] = null
  this[kReplyErrorHandlerCalled] = false
  this[kReplyIsError] = false
  this[kReplyIsRunningOnErrorHook] = false
  this.request = request
  this[kReplyHeaders] = {}
  this[kReplyTrailers] = null
  this[kReplyHasStatusCode] = false
  this[kReplyStartTime] = undefined
  this.log = log
}
Reply.props = []

Object.defineProperties(Reply.prototype, {
  [kRouteContext]: {
    get () {
      return this.request[kRouteContext]
    }
  },
  elapsedTime: {
    get () {
      if (this[kReplyStartTime] === undefined) {
        return 0
      }
      return (this[kReplyEndTime] || now()) - this[kReplyStartTime]
    }
  },
  server: {
    get () {
      return this.request[kRouteContext].server
    }
