  sendTrailer(payload, res, reply)
}

// Splits `payload` in chunks small enough to not overwhelm an HTTP/2 session,
// see HTTP2_MAX_CHUNK_SIZE. Trailers are sent once everything is written.
function sendChunkedPayload (payload, res, reply) {
  // a string cannot be sliced safely, multi-byte characters may be cut in half
  const buffer = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  let offset = 0

  function writeChunks () {
    while (offset < buffer.length) {
      if (isDestroyed(res)) return

      const end = offset + HTTP2_MAX_CHUNK_SIZE
      const hasBackpressure = res.write(buffer.subarray(offset, end)) === false
      offset = end

      if (hasBackpressure && offset < buffer.length) {
        res.once('drain', writeChunks)
        return
      }
    }

    sendTrailer(payload, res, reply)
  }

  writeChunks()
}

